"""Generated by Codex. Check local act inputs and sweep stale files from reused containers."""

import json
import os
from pathlib import Path
import stat
import subprocess
import sys


def check_arguments(arguments):
    """Reject bind mode, including boolean aliases and short flag clusters."""
    for argument in arguments:
        flag, _, value = argument.partition("=")
        if flag == "--bind" or (
            flag.startswith("-") and not flag.startswith("--") and "b" in flag
        ):
            if flag in ("--bind", "-b") and value.lower() in ("false", "f", "0"):
                continue
            raise RuntimeError("Bind mode is disabled by this wrapper; use --bind=false.")


def check_sources(root):
    """Check copy candidates and directory traversal without reading contents."""
    result = subprocess.run(
        ["git", "ls-files", "--cached", "--others", "--exclude-standard", "-z"],
        cwd=root, capture_output=True, check=False,
    )
    # Git can exit successfully after skipping an unreadable untracked directory.
    if result.returncode or result.stderr:
        raise RuntimeError("Cannot enumerate source files: " + os.fsdecode(result.stderr).strip())
    problems = set()
    directories = {root}
    for name in result.stdout.split(b"\0"):
        if not name:
            continue
        path = root / os.fsdecode(name)
        directories.update(parent for parent in path.parents if parent == root or root in parent.parents)
        try:
            mode = path.lstat().st_mode
        except FileNotFoundError:
            continue  # Locally deleted tracked files are not copied.
        except OSError:
            problems.add(str(path.relative_to(root)))
            continue
        if stat.S_ISDIR(mode):
            directories.add(path)
        elif not stat.S_ISLNK(mode) and not os.access(path, os.R_OK):
            problems.add(str(path.relative_to(root)))
    for directory in directories:
        if directory.exists() and not os.access(directory, os.R_OK | os.X_OK):
            problems.add(str(directory.relative_to(root)) + "/")
    if problems:
        paths = "\n".join("  " + repr(path) for path in sorted(problems))
        raise RuntimeError(
            "Unreadable source files or inaccessible directories:\n" + paths
            + "\nRepair only these paths in a host terminal, then rerun. "
            "For a wrong owner, use sudo chown --reference=. -- <path>. "
            "No permissions have been changed."
        )


def check_containers(root):
    """Refuse retained act containers with bind mounts overlapping this checkout."""
    result = subprocess.run(
        ["docker", "ps", "-aq", "--filter", "name=act-"],
        capture_output=True, text=True, check=True,
    )
    ids = result.stdout.split()
    if not ids:
        return
    result = subprocess.run(
        ["docker", "inspect", *ids], capture_output=True, text=True, check=True,
    )
    problems = []
    for container in json.loads(result.stdout):
        for mount in container.get("Mounts", []):
            if mount.get("Type") != "bind":
                continue
            source = Path(mount["Source"]).resolve()
            if source == root or source in root.parents or root in source.parents:
                problems.append(f"  {container['Id'][:12]} {container['Name']}: {source}")
                break
    if problems:
        raise RuntimeError(
            "Retained act containers still bind this checkout:\n" + "\n".join(problems)
            + "\nExport needed artifacts, then stop/remove the listed containers before rerunning. "
            "See .github/run-actions-locally.md#switch-from-bound-containers. "
            "No containers have been changed."
        )


def stale_deleted_paths(root):
    """Paths deleted in git history that are neither tracked nor present locally.

    act copies this checkout into each reused container without deleting, so a
    file removed or renamed upstream stays behind in the container copy and
    can break later builds (e.g. a flat `foo.rs` left next to its replacement
    `foo/` module fails with E0761).
    """
    # --no-renames: a `foo.rs` -> `foo/mod.rs` split is otherwise detected as a
    # rename and the vanished flat file would never be reported as deleted.
    deleted = subprocess.run(
        ["git", "log", "--diff-filter=D", "--no-renames", "--name-only", "--pretty=format:"],
        cwd=root, capture_output=True, text=True, check=False,
    )
    if deleted.returncode:
        return []
    tracked = subprocess.run(
        ["git", "ls-files"], cwd=root, capture_output=True, text=True, check=True,
    ).stdout.splitlines()
    return sorted(
        path for path in {line.strip() for line in deleted.stdout.splitlines()} - set(tracked)
        if path and not path.startswith("/") and ".." not in Path(path).parts
        and not (root / path).exists()
    )


def sweep_stale_files(root):
    """Delete repo-deleted files retained in running act containers' copies.

    Reused containers keep their previous copy of this checkout at the path
    act ran from (Config.WorkingDir); removing the stale paths there mirrors
    this checkout. Only containers whose WorkingDir is this very directory are
    touched. Stopped containers are skipped: `docker rm` them if they cause
    trouble.
    """
    stale = stale_deleted_paths(root)
    if not stale:
        return
    names = subprocess.run(
        ["docker", "ps", "--format", "{{.Names}}", "--filter", "name=act-"],
        capture_output=True, text=True, check=True,
    ).stdout.split()
    if not names:
        return
    inspected = subprocess.run(
        ["docker", "inspect", "--format", "{{.Name}} {{.Config.WorkingDir}}", *names],
        capture_output=True, text=True, check=True,
    ).stdout
    payload = "\n".join(stale) + "\n"
    for line in inspected.splitlines():
        name, _, workdir = line.partition(" ")
        if not workdir:
            continue
        try:
            if not os.path.samefile(root, workdir):
                continue
        except OSError:
            continue  # The path exists only inside the container.
        try:
            result = subprocess.run(
                ["docker", "exec", "-i", name.lstrip("/"), "sh", "-c",
                 'cd "$1" || exit 0; xargs -d "\\n" -r rm -vf --', "sh", workdir],
                input=payload, capture_output=True, text=True, check=False,
            )
        except OSError:
            continue
        removed = [line for line in result.stdout.splitlines() if line.startswith("removed")]
        if removed:
            print(f"act preflight: swept {len(removed)} stale file(s) from container {name.lstrip('/')}")


def main():
    """Fail before any workflow starts if local inputs cannot be used safely."""
    try:
        check_arguments(sys.argv[1:])
        root = Path.cwd().resolve()
        check_sources(root)
        check_containers(root)
        try:
            sweep_stale_files(root)
        except (OSError, subprocess.CalledProcessError) as error:
            print(f"act preflight: stale-file sweep skipped: {error}", file=sys.stderr)
    except (OSError, RuntimeError, ValueError, subprocess.CalledProcessError) as error:
        detail = error.stderr.strip() if isinstance(error, subprocess.CalledProcessError) else str(error)
        print("act preflight: " + detail, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
